head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.table_nm = "";
scwin.mapp_tp_cd = "";
scwin.remk = "";
scwin.column_nm = "";
scwin.comments = "";
scwin.form_cd = "";
scwin.form_ver = "";
scwin.elmt_cd = "";
scwin.elmt_ver = "";
