///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const sbmOptions = {
            id : "sbm_MxDataSet_basinfo_tbl",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_basinfo_tbl=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_MxDataSet_mapping_one",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_mapping_one=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        txb_formnm.setValue("");
        txb_formXPath.setValue("");
        await scwin.basinfoTable();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT95000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

