/**
 * @method
 * @name grd_basinfotbl_OnClick
 * @description grd_basinfotbl 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_basinfotbl_OnClick = async function(row, colid) {
    try {
        scwin.table_nm = MxDataSet_basinfo_tbl.getCellData(row, "TABLE_NM");
        scwin.remk = MxDataSet_basinfo_tbl.getCellData(row, "REMK");
        scwin.mapp_tp_cd = MxDataSet_basinfo_tbl.getCellData(row, "MAPP_TP_CD");
        etc_gubun.setValue("0"); // 기본정보 테이블 변경 할 경우 구분은 해당없음으로
        await scwin.basinfoColumn();
        MxDataSet_mapping_one.removeAll();
        MxDataSet_mapping_one.insertRow();
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TABLE_NM", scwin.table_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TRM_ENG_NM", "");
        // MxDataSet_mapping_one.NameValue(MxDataSet_mapping_one.RowPosition, "MAPP_TP_CD") = mapp_tp_cd;
        let unitFormChk = cbo_unitForm.getSelectedIndex() + 1;
        if (unitFormChk === "0") {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD", "0");
        } else {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD", "2");
        }
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "OWNR_FORM_CD", scwin.ownr_form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "OWNR_FORM_VER", scwin.ownr_form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_CD", scwin.form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_VER", scwin.form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_CD", scwin.elmt_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_VER", scwin.elmt_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_X_PATH", scwin.form_x_path);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FSS_ELMT_ID", "");
        let ssval = $c.cp.valueOfIndex(comboFormGubun, "Column1", comboFormGubun.getSelectedIndex());
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "LD_MKT_TP_CD", ssval);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT95000.grd_basinfotbl_OnClick" });
    }
};

/**
 * @method
 * @name grd_basinfocol_OnClick
 * @description grd_basinfocol 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_basinfocol_OnClick = async function(row, colid) {
    try {
        scwin.table_nm = MxDataSet_basinfo_col.getCellData(row, "TABLE_NM");
        scwin.column_nm = MxDataSet_basinfo_col.getCellData(row, "COLUMN_NM");
        scwin.comments = MxDataSet_basinfo_col.getCellData(row, "COMMENTS");
        etc_gubun.setValue("0"); // 기본정보 항목 변경 할 경우 구분은 해당없음으로
        await scwin.mappingList("combas");
        MxDataSet_mapping_one.removeAll();
        MxDataSet_mapping_one.insertRow();
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TABLE_NM", scwin.table_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TRM_ENG_NM", scwin.column_nm);
        // MxDataSet_mapping_one.NameValue(MxDataSet_mapping_one.RowPosition, "MAPP_TP_CD") = mapp_tp_cd;
        let unitFormChk = cbo_unitForm.getSelectedIndex() + 1;
        if (unitFormChk === "0") {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD", "0");
        } else {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD", "2");
        }
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "OWNR_FORM_CD", scwin.ownr_form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "OWNR_FORM_VER", scwin.ownr_form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_CD", scwin.form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_VER", scwin.form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_CD", scwin.elmt_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_VER", scwin.elmt_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_X_PATH", scwin.form_x_path);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FSS_ELMT_ID", "");
        let ssval = $c.cp.valueOfIndex(comboFormGubun, "Column1", comboFormGubun.getSelectedIndex());
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "LD_MKT_TP_CD", ssval);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT95000.grd_basinfocol_OnClick" });
    }
};

/**
 * @method
 * @name form_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.form_search_onclick = async function() {
    try {
        cbo_unitForm.setSelectedIndex(-1);
        txb_formXPath.setValue("");
        scwin.formnm_row = "0";
        await scwin.formSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT95000.form_search_onclick" });
    }
};

/**
 * @method
 * @name grid_formnm_OnClick
 * @description grid_formnm 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grid_formnm_OnClick = async function(row, colid) {
    try {
        cbo_unitForm.setSelectedIndex(-1);
        txb_formXPath.setValue("");
        scwin.ownr_form_cd = MxDataSet_form.getCellData(row, "OWNR_FORM_CD");
        scwin.ownr_form_ver = MxDataSet_form.getCellData(row, "OWNR_FORM_VER");
        scwin.form_cd = MxDataSet_form.getCellData(row, "OWNR_FORM_CD");
        txb_formXPath.setValue("");
        scwin.formnm_row = row;
        await scwin.formItmSearch();
        MxDataSet_mapping_one.removeAll();
        MxDataSet_mapping_one.insertRow();
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "OWNR_FORM_CD", scwin.ownr_form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "OWNR_FORM_VER", scwin.ownr_form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TABLE_NM", scwin.table_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TRM_ENG_NM", scwin.column_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD", scwin.mapp_tp_cd);
        let formgubun = $c.cp.valueOfIndex(comboFormGubun, "Column1", comboFormGubun.getSelectedIndex());
        if (formgubun !== "9") {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_CD", "");
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_VER", "");
        } else {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_CD", scwin.ownr_form_cd);
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_VER", scwin.ownr_form_ver);
            scwin.form_ver = MxDataSet_form.getCellData(row, "OWNR_FORM_VER");
        }
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_CD", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_VER", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FSS_ELMT_ID", "");
        let ssval = $c.cp.valueOfIndex(comboFormGubun, "Column1", comboFormGubun.getSelectedIndex());
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "LD_MKT_TP_CD", ssval);
        await scwin.mappingList("formbas");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT95000.grid_formnm_OnClick" });
    }
};

/**
 * @method
 * @name grid_formitm_OnClick
 * @description grid_formitm 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grid_formitm_OnClick = async function(row, colid) {
    try {
        scwin.form_cd = MxDataSet_form_itm.getCellData(row, "FORM_CD");
        scwin.form_ver = MxDataSet_form_itm.getCellData(row, "FORM_VER");
        scwin.elmt_cd = MxDataSet_form_itm.getCellData(row, "ELMT_CD");
        scwin.elmt_ver = MxDataSet_form_itm.getCellData(row, "ELMT_VER");
        scwin.form_x_path = MxDataSet_form_itm.getCellData(row, "FORM_X_PATH");
        txb_formXPath.setValue(scwin.form_x_path);
        await scwin.mappingOne();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT95000.grid_formitm_OnClick" });
    }
};

/**
