 */
scwin.MxLogicalTr_mapping_save_OnSuccess = async function() {
    try {
        await $c.win.alert('저장이 완료되었습니다.');
        txb_formXPath.setValue("");
        MxDataSet_mapping_one.removeAll();
        await scwin.mappingList("formitmbas");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT95000.MxLogicalTr_mapping_save_OnSuccess" });
    }
};

