/**
 * @method
 * @name txb_formnm_onkeydown
 * @description txb_formnm 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_formnm_onkeydown = async function() {
    try {
        if (window.event.keyCode === "13") {
            cbo_unitForm.setSelectedIndex(-1);
            txb_formXPath.setValue("");
            scwin.formnm_row = "0";
            await scwin.formSearch();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT95000.txb_formnm_onkeydown" });
    }
};

