/**
 * @method
 * @name basinfoTable
 * @description basinfo Table 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.basinfoTable = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_basinfo_tbl",
        action : "/kclic.do",
        ref : "",
        target : "MxDataSet_basinfo_tbl=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
