/**
 * @method
 * @name mappingSave
 * @description mapping Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.mappingSave = async function() {
    t_TableNm = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getRowPosition(), "TABLE_NM");
    t_TrmEngNm = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getRowPosition(), "TRM_ENG_NM");
    t_EtcGubunValue = etc_gubun.getValue();
    let ssval = $c.cp.valueOfIndex(comboFormGubun, "Column1", comboFormGubun.getSelectedIndex());
    if (t_EtcGubunValue === "0") {
        if (t_TableNm === "") {
            await $c.win.alert("기본정보 테이블을 선택하십시오.");
            return;
        }
        if (t_TrmEngNm === "") {
            await $c.win.alert("기본정보 항목을 선택하십시오.");
            return;
        }
    }
    if (ssval !== "9") {
        // 서식검색이 금감원이 아닐 경우
        if (txb_formXPath.getValue() === "") {
            await $c.win.alert("서식(서식명, 항목)을 선택하십시오.");
            return;
        }
    }
    if (ssval === "9") {
        // 서식검색이 금감원일 경우
        scwin.elmt_cd = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_CD");
        if (scwin.elmt_cd === "") {
            await $c.win.alert("금감원 서식일 경우 엘리먼트 코드를 입력하십시오");
            return;
        }
        scwin.mapp_tp_cd = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD");
        if (scwin.mapp_tp_cd !== "A" && scwin.mapp_tp_cd !== "B" && scwin.mapp_tp_cd !== "C" && scwin.mapp_tp_cd !== "D" && scwin.mapp_tp_cd !== "E" && scwin.mapp_tp_cd !== "F") {
            await $c.win.alert("금감원 서식일 경우 구분값을 A, B, C, D, E, F 중 입력하십시오");
            return;
        }
        scwin.fss_elmt_id = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getRowPosition(), "FSS_ELMT_ID");
        if (scwin.fss_elmt_id === "") {
            await $c.win.alert("금감원 서식일 경우 FSS_ELMT_ID를 입력하십시오");
            return;
        }
    }
    if (confirm("저장하시겠습니까?")) {
        MxLogicalTr_mapping_save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_MxLogicalTr_mapping_save",
            action : "/kclic.do",
            ref : "MxDataSet_mapping_one",
            target : "MxLogicalTr_mapping_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        MxDataSet_mapping_one.removeAll();
    }
};

/**
 * @method
 * @name mappingModify
 * @description mapping Modify 처리
