 */
scwin.mappingModify = async function() {
    let ssval = $c.cp.valueOfIndex(comboFormGubun, "Column1", comboFormGubun.getSelectedIndex());
    if (scwin.ownr_form_cd === "" || scwin.ownr_form_ver === "") {
        await $c.win.alert("서식명을 선택하십시오.");
        return;
    }
    if (scwin.formnm_row === 0) {
        await $c.win.alert("서식명을 선택하십시오.");
        return;
    }
    const m_form_ver = MxDataSet_form.getCellData(scwin.formnm_row, "OWNR_FORM_VER");
    if (typeof m_form_ver !== "undefined" && m_form_ver !== "") {
        let maxVal;
        let tmpVal1;
        let tmpVal2;
        const f_form_ver = parseFloat(m_form_ver);
        if (f_form_ver === maxVal) {
            await $c.win.alert("같은 폼 버전의 데이터가 있어 서식버전 업데이트를 할 수 없습니다.");
        } else {
            if (confirm("서식버전을 변경하시겠습니까?")) {
                const sbmOptions = {
                    id : "sbm_MxDataSet_mapping_list",
                    action : "/kclic.do",
                    ref : "",
                    target : "MxDataSet_mapping_list=body.content",
                    isProcessMsg : false
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            }
        }
    } else {
        await $c.win.alert("변경할 데이터가 업습니다.");
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {*} sval sval
 * @param {*} sval2 sval2
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(sval, sval2) {
    let delCnt = 0;
    if (!scwin.cntDatasetRowCheck(sval)) {
        await $c.win.alert("체크사항이 없습니다.");
        return;
    } else {
        for (i = sval.getRowCount(); i > 0; i--) {
            if (sval.getCellData(i, "CHK_FLAG") === "T") {
                delCnt++;
                // sval.DeleteRow(i);

            }
        }
    }
    if (confirm(delCnt + "건을 삭제하시겠습니까?")) {
        for (i = sval.getRowCount(); i > 0; i--) {
            if (sval.getCellData(i, "CHK_FLAG") === "T") {
                sval.DeleteRow(i);
            }
        }
        MxLogicalTr_mapping_delete.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_MxLogicalTr_mapping_delete",
            action : "/kclic.do",
            ref : "MxDataSet_mapping_list",
            target : "MxLogicalTr_mapping_delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name mappingOne
 * @description mapping One 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.mappingOne = async function() {
    MxDataSet_mapping_one.removeAll();
    MxDataSet_mapping_one.insertRow();
    if (etc_gubun.getValue() === '3' || etc_gubun.getValue() === '1' || etc_gubun.getValue() === '5' || etc_gubun.getValue() === '6') {
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TABLE_NM", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TRM_ENG_NM", "");
    } else {
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TABLE_NM", scwin.table_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "TRM_ENG_NM", scwin.column_nm);
    }
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "OWNR_FORM_CD", scwin.ownr_form_cd);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "OWNR_FORM_VER", scwin.ownr_form_ver);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_CD", scwin.form_cd);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_VER", scwin.form_ver);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_CD", scwin.elmt_cd);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "ELMT_VER", scwin.elmt_ver);
    if (etc_gubun.getValue() === '3' || etc_gubun.getValue() === '1' || etc_gubun.getValue() === '2' || etc_gubun.getValue() === '4' || etc_gubun.getValue() === '5' || etc_gubun.getValue() === '6') {
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD", etc_gubun.getValue());
    } else {
        let unitFormChk = cbo_unitForm.getSelectedIndex() + 1;
        if (unitFormChk === "0") {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD", "0");
        } else {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "MAPP_TP_CD", "7");
        }
    }
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FSS_ELMT_ID", "");
    let ssval = $c.cp.valueOfIndex(comboFormGubun, "Column1", comboFormGubun.getSelectedIndex());
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "LD_MKT_TP_CD", ssval);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getRowPosition(), "FORM_X_PATH", scwin.form_x_path);
    if (etc_gubun.getValue() === '3' || etc_gubun.getValue() === '1' || etc_gubun.getValue() === '6') {
        await scwin.mappingList("etcbas");
    } else {
        await scwin.mappingList("formitmbas");
    }
};

/**
 * @method
 * @name cntDatasetRowCheck
 * @description 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    cCnt = 0;
    for (i = 1; i <= sval.getRowCount(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") === "T") {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name etcCheck
 * @description etc Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etcCheck = async function() {
    let ssval = $c.cp.valueOfIndex(comboFormGubun, "Column1", comboFormGubun.getSelectedIndex());
    if (etc_gubun.getValue() === '3') {
        if (confirm("대규모 법인여부를 선택하시겠습니까?")) {
            if (ssval !== "9") {
                if (txb_formXPath.getValue() === "") {
                    await $c.win.alert("기본정보(테이블, 항목)와 서식(서식명, 항목)을 선택하십시오.");
                    etc_gubun.setValue("0");
                    return;
                }
            }
            await scwin.mappingOne();
        } else {
            etc_gubun.setValue("0");
            await scwin.mappingOne();
            return;
        }
    }
    if (etc_gubun.getValue() === '6') {
        if (confirm("대기업여부를 선택하시겠습니까?")) {
            await scwin.mappingOne();
        }
    }
    if (etc_gubun.getValue() === '1') {
        if (confirm("지배회사의 연결자산 총액대비계산을 선택하시겠습니까?")) {
            if (ssval !== "9") {
                if (txb_formXPath.getValue() === "") {
                    await $c.win.alert("기본정보(테이블, 항목)와 서식(서식명, 항목)을 선택하십시오.");
                    etc_gubun.setValue("0");
                    return;
                }
            }
            await scwin.mappingOne();
        } else {
            etc_gubun.setValue("0");
            await scwin.mappingOne();
            return;
        }
    } else {
        await scwin.mappingOne();
    }
};
